-- Sprint 1c (D-041): the Let's talk page's own hero image (one landscape image, shown behind the top of the page): a door ajar at the end of a dark corridor, warm orange light spilling out.
-- Generated by scripts/build-hero-photos.mjs --replace; the encoded image(s) are in design/hero/. The slot's current
-- photo is superseded (BR-1.17: kept, never altered or deleted) and the new one becomes current — the owner can replace
-- it in Admin → Photos at any time. Additive only.


UPDATE "ProfilePhoto" SET "supersededAt" = now() WHERE "purpose" = 'hero-contact' AND "supersededAt" IS NULL AND "sha256" <> 'c9ac044c138e67359f1904cd3327e38ef6ae6df1d292398a8f42ce8de8236b25';

INSERT INTO "ProfilePhoto" ("id", "purpose", "altText", "mimeType", "width", "height", "byteSize", "sha256", "fileData")
SELECT gen_random_uuid()::text, 'hero-contact', 'A decorative image behind the top of the page', 'image/webp', 1280, 853, 22366, 'c9ac044c138e67359f1904cd3327e38ef6ae6df1d292398a8f42ce8de8236b25', decode('', 'base64')
WHERE NOT EXISTS (SELECT 1 FROM "ProfilePhoto" WHERE "purpose" = 'hero-contact' AND "supersededAt" IS NULL);
